SELECT id, name, code, dept_id, phone, address, province, city, district, business_hours, open_time, close_time, rest_days, status, sort, remark, create_time FROM salon_store
deleted = 0
AND ( name LIKE CONCAT('%', #{q.keywords}, '%') OR code LIKE CONCAT('%', #{q.keywords}, '%') OR phone LIKE CONCAT('%', #{q.keywords}, '%') OR address LIKE CONCAT('%', #{q.keywords}, '%') )
AND status = #{q.status}
AND dept_id = #{q.deptId}
ORDER BY sort ASC, create_time DESC
